public static boolean blocks(PanelCoverHost host, Direction side) {
    var cover = host.getCover(side);
    if (cover.isEmpty()) return false;
    var id = CoverItems.behavior(cover);
    if (host.panels().shuttered(side)) return true;
    if (CoverItems.REDSTONE_TORCH.equals(id) || CoverItems.REDSTONE_REPEATER.equals(id)) return true;
    var owner = host.coverOwner();
    var level = owner.getLevel();
    return CoverUtilityBehaviors.FILTER_ITEM.equals(id)
            && owner instanceof com.gregtech.gregtech.blockentity.machine.ItemPipeBlockEntity
            && level != null
            && level.getBlockEntity(owner.getBlockPos().relative(side)) instanceof com.gregtech.gregtech.blockentity.machine.ItemPipeBlockEntity;
}

